  `extra_config` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展配置（JSON格式）',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SmsKey表';
